// ════════════════════════════════════════════════════════════════
// SURGICAL STRIKE v5.0 — FMP SCANNER ENGINE (intraday momentum)
// Data source: Financial Modeling Prep (stable API)
// Requires n8n variable: FMP_API_KEY
// Output: { formatted, raw: { setups:[...], macro:{...} } }
// ════════════════════════════════════════════════════════════════
const KEY = $vars.FMP_API_KEY;
if (!KEY) {
  return [{ json: { formatted: 'ERROR: FMP_API_KEY not set in n8n variables.', raw: { setups: [], macro: {} }, error: true } }];
}
const BASE = 'https://financialmodelingprep.com';

// ---- tunables (override via n8n vars) ----
const MIN_PRICE      = Number($vars.MIN_PRICE      || 3);
const MAX_PRICE      = Number($vars.MAX_PRICE      || 600);
const MIN_DOLLAR_VOL = Number($vars.MIN_DOLLAR_VOL || 10000000); // $10M avg daily $-vol
const MIN_RVOL       = Number($vars.MIN_RVOL       || 1.3);
const MIN_CHANGE_PCT = Number($vars.MIN_CHANGE_PCT || 2);
const MAX_CANDIDATES = Number($vars.MAX_CANDIDATES || 40); // how many movers to deep-scan
const EARN_BLACKOUT_DAYS = Number($vars.EARN_BLACKOUT_DAYS || 2);

const num = (x, d = 0) => { const n = Number(x); return Number.isFinite(n) ? n : d; };
const safeGet = (o, ...keys) => { for (const k of keys) { if (o && o[k] != null) return o[k]; } return undefined; };

async function fmp(path, params = {}) {
  const qs = new URLSearchParams({ ...params, apikey: KEY }).toString();
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: `${BASE}${path}?${qs}`, json: true, timeout: 20000
    });
    return res;
  } catch (e) {
    return { __error: String(e && e.message || e) };
  }
}

// ---- MATH ----
function computeATR(daily, period = 14) {
  if (!daily || daily.length < period + 1) return null;
  const bars = [...daily].sort((a, b) => new Date(a.date) - new Date(b.date));
  const trs = [];
  for (let i = 1; i < bars.length; i++) {
    const h = num(bars[i].high), l = num(bars[i].low), pc = num(bars[i - 1].close);
    trs.push(Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc)));
  }
  if (trs.length < period) return null;
  let atr = trs.slice(0, period).reduce((a, b) => a + b, 0) / period;
  for (let i = period; i < trs.length; i++) atr = (atr * (period - 1) + trs[i]) / period;
  return atr;
}
function computeVWAP(bars) {
  let pv = 0, vol = 0;
  for (const b of bars) {
    const v = num(b.volume);
    if (v <= 0) continue;
    const typical = (num(b.high) + num(b.low) + num(b.close)) / 3;
    pv += typical * v; vol += v;
  }
  return vol > 0 ? pv / vol : null;
}
function avgVol(daily, lookback = 20) {
  const bars = [...daily].sort((a, b) => new Date(b.date) - new Date(a.date));
  const hist = bars.slice(0, lookback).map(b => num(b.volume)).filter(v => v > 0);
  if (!hist.length) return null;
  return hist.reduce((a, b) => a + b, 0) / hist.length;
}
function high52(daily) {
  const hs = daily.map(b => num(b.high)).filter(h => h > 0);
  return hs.length ? Math.max(...hs) : null;
}

// ════════════ MACRO CONTEXT ════════════
async function buildMacro() {
  const [spy, qqq, vix] = await Promise.all([
    fmp.call(this, '/stable/quote', { symbol: 'SPY' }),
    fmp.call(this, '/stable/quote', { symbol: 'QQQ' }),
    fmp.call(this, '/stable/quote', { symbol: '^VIX' }),
  ]);
  const q = (r) => Array.isArray(r) ? r[0] : (r || {});
  const spyQ = q(spy), qqqQ = q(qqq), vixQ = q(vix);
  const spyChg = num(safeGet(spyQ, 'changePercentage', 'changesPercentage'));
  const qqqChg = num(safeGet(qqqQ, 'changePercentage', 'changesPercentage'));
  const vixLevel = num(safeGet(vixQ, 'price'), null);

  // session by exchange time (assume ET; n8n server may differ — informational only)
  const now = new Date();
  const etHour = (now.getUTCHours() - 4 + 24) % 24; // rough ET (EDT)
  let session = 'Closed';
  if (etHour >= 4 && etHour < 9) session = 'Pre-Market';
  else if (etHour === 9 || (etHour < 16 && etHour >= 9)) session = 'Regular';
  else if (etHour >= 16 && etHour < 20) session = 'After-Hours';

  // regime: simple, transparent. GREEN = risk-on, RED = risk-off, YELLOW = mixed.
  let regime = 'YELLOW', sizing = 'NORMAL';
  if (spyChg > 0.3 && qqqChg > 0.3 && (vixLevel == null || vixLevel < 20)) { regime = 'GREEN'; sizing = 'FULL'; }
  else if (spyChg < -1 || (vixLevel != null && vixLevel > 28)) { regime = 'RED'; sizing = 'NONE'; }
  else if (vixLevel != null && vixLevel > 22) { sizing = 'HALF'; }

  const validWindow = session === 'Regular' || session === 'Pre-Market';
  return {
    session, regime, sizing,
    spyPrice: num(spyQ.price), spyChg: Number(spyChg.toFixed(2)),
    qqqPrice: num(qqqQ.price), qqqChg: Number(qqqChg.toFixed(2)),
    vixLevel: vixLevel != null ? Number(vixLevel.toFixed(2)) : null,
    vixStatus: vixLevel == null ? 'Unknown' : vixLevel > 28 ? 'High Fear' : vixLevel > 20 ? 'Elevated' : 'Calm',
    validWindow,
  };
}

// ════════════ CATALYST CLASSIFICATION ════════════
function classifyCatalyst(newsItems) {
  if (!newsItems || !newsItems.length) return { tier: 'NONE', headline: '', ageHours: null };
  // newest first
  const items = [...newsItems].sort((a, b) =>
    new Date(b.publishedDate || b.date || 0) - new Date(a.publishedDate || a.date || 0));
  const top = items[0];
  const headline = String(safeGet(top, 'title', 'text') || '').slice(0, 140);
  const pubDate = new Date(top.publishedDate || top.date || Date.now());
  const ageHours = Math.max(0, (Date.now() - pubDate.getTime()) / 3.6e6);
  const h = headline.toLowerCase();
  const TIER1 = ['fda', 'approval', 'acquisition', 'acquire', 'merger', 'buyout', 'guidance', 'beats', 'raises', 'contract award', 'partnership with', 'phase 3', 'authorization'];
  const TIER2 = ['upgrade', 'price target', 'initiates', 'launch', 'unveils', 'expansion', 'collaboration', 'milestone', 'patent'];
  let tier = 'WEAK';
  if (ageHours > 48) tier = 'NONE';
  else if (TIER1.some(k => h.includes(k))) tier = 'TIER_1';
  else if (TIER2.some(k => h.includes(k))) tier = 'TIER_2';
  return { tier, headline, ageHours: Number(ageHours.toFixed(1)) };
}

// ════════════ MAIN ════════════
const macro = await buildMacro.call(this);

// 1) Get the universe of movers (gainers + most active), dedup
const [gainers, actives] = await Promise.all([
  fmp.call(this, '/stable/biggest-gainers'),
  fmp.call(this, '/stable/most-actives'),
]);
const moverRows = []
  .concat(Array.isArray(gainers) ? gainers : [])
  .concat(Array.isArray(actives) ? actives : []);

// dedup by symbol, basic pre-filter on price + change
const seen = new Set();
const universe = [];
for (const r of moverRows) {
  const sym = safeGet(r, 'symbol', 'ticker');
  if (!sym || seen.has(sym)) continue;
  if (/[.\-]/.test(sym)) continue; // skip class shares / weird tickers
  const price = num(safeGet(r, 'price'));
  const chg = num(safeGet(r, 'changePercentage', 'changesPercentage'));
  if (price < MIN_PRICE || price > MAX_PRICE) continue;
  if (Math.abs(chg) < MIN_CHANGE_PCT) continue;
  seen.add(sym);
  universe.push({ symbol: sym, price, chg });
}
const shortlist = universe.slice(0, MAX_CANDIDATES);

// 2) Earnings calendar (next 7d) to flag blackout
const today = new Date();
const in7 = new Date(today.getTime() + 7 * 864e5);
const fmtD = (d) => d.toISOString().slice(0, 10);
const earnCal = await fmp.call(this, '/stable/earnings-calendar', { from: fmtD(today), to: fmtD(in7) });
const earnMap = {};
if (Array.isArray(earnCal)) {
  for (const e of earnCal) {
    const sym = safeGet(e, 'symbol');
    const d = e.date || e.epsDate;
    if (sym && d) {
      const days = Math.ceil((new Date(d) - today) / 864e5);
      if (earnMap[sym] == null || days < earnMap[sym]) earnMap[sym] = days;
    }
  }
}

// SPY change for RS calc
const spyChg = macro.spyChg;

// 3) Deep-scan each shortlisted symbol
const setups = [];
for (const cand of shortlist) {
  const sym = cand.symbol;
  const [quoteR, dailyR, intraR, profileR, newsR] = await Promise.all([
    fmp.call(this, '/stable/quote', { symbol: sym }),
    fmp.call(this, '/stable/historical-price-eod/full', { symbol: sym }),
    fmp.call(this, '/stable/historical-chart/5min', { symbol: sym }),
    fmp.call(this, '/stable/profile', { symbol: sym }),
    fmp.call(this, '/stable/news/stock', { symbols: sym, limit: 5 }),
  ]);

  const quote = Array.isArray(quoteR) ? quoteR[0] : quoteR;
  if (!quote || quote.__error) continue;

  // daily history may be {historical:[...]} or [...]
  let daily = Array.isArray(dailyR) ? dailyR : (dailyR && dailyR.historical) ? dailyR.historical : [];
  if (!daily.length) continue;
  daily = daily.slice(0, 60); // last ~60 trading days

  const intra = Array.isArray(intraR) ? intraR : [];
  const profile = Array.isArray(profileR) ? profileR[0] : profileR;
  const news = Array.isArray(newsR) ? newsR : (newsR && newsR.content) ? newsR.content : [];

  const price = num(safeGet(quote, 'price'), cand.price);
  const chg = num(safeGet(quote, 'changePercentage', 'changesPercentage'), cand.chg);
  const todayVol = num(safeGet(quote, 'volume'));
  const avgDailyVol = avgVol(daily) || num(safeGet(quote, 'avgVolume'));
  const rvol = (avgDailyVol > 0) ? todayVol / avgDailyVol : null;
  const avgDollarVol = (avgDailyVol || 0) * price;

  // liquidity + rvol gates
  if (avgDollarVol < MIN_DOLLAR_VOL) continue;
  if (rvol != null && rvol < MIN_RVOL) continue;

  const atr14 = computeATR(daily);
  const vwap = computeVWAP(intra);
  const distanceFromVWAP = (vwap && price) ? ((price - vwap) / vwap) * 100 : null;
  const aboveVWAP = (vwap != null) ? price >= vwap : null;

  const yr = high52(daily);
  const nearHighPct = (yr && yr > 0) ? Math.min(100, (price / yr) * 100) : null;

  const rsVsSpy = Number((chg - spyChg).toFixed(2));

  // entry/stop/targets — intraday momentum model
  // stop = max(VWAP undercut, 1*ATR-based) ; entry zone = current to +0.3 ATR
  let stopLoss = null, riskPerShare = null, entryZone = null, tp1 = null, tp2 = null;
  if (atr14 && price) {
    const atrStop = price - atr14;
    const vwapStop = (vwap != null) ? vwap - (0.25 * atr14) : atrStop;
    stopLoss = Number(Math.max(0.01, Math.min(atrStop, vwapStop) > 0 ? Math.max(atrStop, vwapStop) : atrStop).toFixed(2));
    // use the tighter of the two sensible stops but never above price
    stopLoss = Number(Math.min(price - 0.01, Math.max(vwapStop, atrStop)).toFixed(2));
    riskPerShare = Number((price - stopLoss).toFixed(2));
    if (riskPerShare > 0) {
      tp1 = Number((price + 2 * riskPerShare).toFixed(2));
      tp2 = Number((price + 3 * riskPerShare).toFixed(2));
      entryZone = `${price.toFixed(2)}–${(price + 0.3 * atr14).toFixed(2)}`;
    }
  }
  const rewardRisk = (riskPerShare > 0 && tp1) ? Number(((tp1 - price) / riskPerShare).toFixed(2)) : null;

  const cat = classifyCatalyst(news);

  const daysToEarnings = earnMap[sym];
  const earningsBlackout = (daysToEarnings != null && daysToEarnings >= 0 && daysToEarnings <= EARN_BLACKOUT_DAYS);

  setups.push({
    symbol: sym,
    sector: safeGet(profile, 'sector') || '',
    price: Number(price.toFixed(2)),
    chg: Number(chg.toFixed(2)),
    rsVsSpy,
    volumeRatio: rvol != null ? Number(rvol.toFixed(2)) : null,
    volumeStatus: rvol == null ? 'unknown' : rvol >= 2 ? 'surge' : rvol >= 1.3 ? 'elevated' : 'normal',
    avgDollarVol: Math.round(avgDollarVol),
    atr14: atr14 != null ? Number(atr14.toFixed(2)) : null,
    vwap: vwap != null ? Number(vwap.toFixed(2)) : null,
    aboveVWAP,
    distanceFromVWAP: distanceFromVWAP != null ? Number(distanceFromVWAP.toFixed(2)) : null,
    nearHighPct: nearHighPct != null ? Number(nearHighPct.toFixed(1)) : null,
    entryZone,
    stopLoss,
    riskPerShare,
    tp1, tp2,
    rewardRisk,
    catalystTier: cat.tier,
    catalystHeadline: cat.headline,
    catalystAgeHours: cat.ageHours,
    daysToEarnings: daysToEarnings != null ? daysToEarnings : null,
    earningsBlackout,
    grade: null, // assigned in rank node
  });
}

// quick human-readable summary
const lines = [];
lines.push(`SURGICAL STRIKE v5.0 SCAN — ${new Date().toISOString()}`);
lines.push(`Regime: ${macro.regime} | SPY ${macro.spyChg}% | QQQ ${macro.qqqChg}% | VIX ${macro.vixLevel}`);
lines.push(`Universe: ${universe.length} movers → deep-scanned ${shortlist.length} → ${setups.length} passed gates`);
for (const s of setups.slice(0, 15)) {
  lines.push(`  ${s.symbol} $${s.price} ${s.chg >= 0 ? '+' : ''}${s.chg}% RVOL ${s.volumeRatio}x RS ${s.rsVsSpy} cat:${s.catalystTier} R/R ${s.rewardRisk}`);
}
const formatted = lines.join('\n');

return [{ json: { formatted, raw: { setups, macro }, scanTimestamp: new Date().toISOString() } }];

// ════════════════════════════════════════════════════════════════
// QUANT RANK — transparent additive score, assigns grade, builds payloads
// This is the IDEA-SURFACING core. No LLM here — pure, repeatable formula.
// ════════════════════════════════════════════════════════════════
const data = $input.first().json;
const setups = (data.raw && data.raw.setups) || [];
const macro = (data.raw && data.raw.macro) || {};
const num = (x, d = 0) => { const n = Number(x); return Number.isFinite(n) ? n : d; };

if (!setups.length) {
  return [{ json: { top10: [], macro, formatted: data.formatted, scanTimestamp: data.scanTimestamp, rankSkipped: true, reason: 'No setups from scanner' } }];
}

function score(s) {
  const p = {};
  const rvol = num(s.volumeRatio);
  if (rvol >= 3) p.rvol = 30; else if (rvol >= 2) p.rvol = 22; else if (rvol >= 1.5) p.rvol = 14; else if (rvol >= 1.2) p.rvol = 6; else p.rvol = -25;
  const rs = num(s.rsVsSpy);
  if (rs > 3) p.rs = 15; else if (rs > 1.5) p.rs = 9; else if (rs > 0) p.rs = 4; else p.rs = -5;
  if (s.catalystTier === 'TIER_1') p.cat = 25; else if (s.catalystTier === 'TIER_2') p.cat = 12; else if (s.catalystTier === 'WEAK') p.cat = 4; else p.cat = 0;
  const nh = num(s.nearHighPct);
  if (nh >= 97) p.nh = 12; else if (nh >= 90) p.nh = 7; else if (nh >= 80) p.nh = 3; else p.nh = 0;
  p.vwap = (s.aboveVWAP === true) ? 10 : (s.aboveVWAP === false ? -10 : 0);
  const rr = num(s.rewardRisk);
  if (rr >= 3) p.rr = 15; else if (rr >= 2) p.rr = 10; else if (rr >= 1.5) p.rr = 4; else p.rr = -15;
  const dist = num(s.distanceFromVWAP);
  if (dist > 4) p.ext = -25; else if (dist > 2.5) p.ext = -12; else p.ext = 0;
  if (s.earningsBlackout === true) p.earn = -1000;
  if (num(s.price) < 1) p.penny = -1000;
  if (num(s.avgDollarVol) > 0 && num(s.avgDollarVol) < 5000000) p.liq = -40;
  const total = Object.values(p).reduce((a, b) => a + b, 0);
  return { total, parts: p };
}

function gradeOf(sc) {
  if (sc >= 80) return 'A';
  if (sc >= 55) return 'B';
  if (sc >= 30) return 'C';
  return 'D';
}

const scored = setups
  .filter(s => s.symbol && s.price)
  .map(s => { const r = score(s); return { ...s, councilScore: Math.round(r.total), scoreBreakdown: r.parts, grade: gradeOf(r.total) }; })
  .filter(s => s.earningsBlackout !== true && s.councilScore > -900)
  .sort((a, b) => b.councilScore - a.councilScore);

const top10 = scored.slice(0, 10);

const payloads = top10.map(s => ({
  ticker: s.symbol, grade: s.grade, sector: s.sector, price: s.price, change_pct: s.chg,
  rs_vs_spy: s.rsVsSpy, volume_ratio: s.volumeRatio, volume_status: s.volumeStatus,
  avg_dollar_vol: s.avgDollarVol, atr14: s.atr14, entry_zone: s.entryZone, stop_loss: s.stopLoss,
  risk_per_share: s.riskPerShare, tp1: s.tp1, tp2: s.tp2, reward_risk: s.rewardRisk,
  near_high_pct: s.nearHighPct, vwap: s.vwap, distance_from_vwap_pct: s.distanceFromVWAP,
  above_vwap: s.aboveVWAP, catalyst_tier: s.catalystTier, catalyst_headline: s.catalystHeadline,
  catalyst_age_hours: s.catalystAgeHours, days_to_earnings: s.daysToEarnings,
  earnings_blackout: s.earningsBlackout, council_score: s.councilScore, score_breakdown: s.scoreBreakdown
}));

return [{ json: { top10: payloads, totalScanned: setups.length, macro, formatted: data.formatted, scanTimestamp: data.scanTimestamp, rankTimestamp: new Date().toISOString() } }];

const data = $input.first().json;
if (!data.top10 || data.top10.length === 0) {
  return [{ json: { ...data, abort: true, abortReason: data.reason || 'No stocks passed scanner filters today' } }];
}
return [{ json: { ...data, abort: false } }];

const data = $input.first().json;
const apiKey = $vars.ANTHROPIC_API_KEY || $env.ANTHROPIC_API_KEY;
const MODEL = $vars.ANTHROPIC_MODEL || 'claude-sonnet-4-20250514';
const PERSONA = "You are the BALANCED REVIEWER. Look for both risks and genuine strengths with equal weight.";
const http = this.helpers.httpRequest.bind(this);
function fallback(ticker, reason='Model returned unparseable response') {
  return { ticker, verdict: 'CLEAR', confidence: 50, upgrade_signals: [], red_flags: ['parse_error'], reason, force_skip: false, size_view: 'full' };
}
function sanitize(p, ticker) {
  const verdicts = ['STRONG','CLEAR','WEAK','SKIP','FORCE_SKIP'];
  const sizes = ['increase','full','reduce','half','zero'];
  p.ticker = ticker;
  p.verdict = verdicts.includes(String(p.verdict).toUpperCase()) ? String(p.verdict).toUpperCase() : 'CLEAR';
  p.confidence = Math.max(0, Math.min(100, Math.round(Number(p.confidence ?? 50))));
  p.upgrade_signals = Array.isArray(p.upgrade_signals) ? p.upgrade_signals : [];
  p.red_flags = Array.isArray(p.red_flags) ? p.red_flags : [];
  p.reason = String(p.reason || '').split(/\s+/).slice(0,25).join(' ') || 'No specific concern found';
  p.force_skip = p.force_skip === true || p.verdict === 'FORCE_SKIP';
  p.size_view = sizes.includes(p.size_view) ? p.size_view : (p.verdict === 'SKIP' || p.force_skip ? 'zero' : 'full');
  return p;
}
function parse(text, ticker) {
  try {
    const clean = String(text || '').replace(/```json|```/g, '').trim();
    const match = clean.match(/\{[\s\S]*\}/);
    return sanitize(JSON.parse(match ? match[0] : clean), ticker);
  } catch (e) {
    return fallback(ticker);
  }
}
async function callOne(payload) {
  if (!apiKey) return {
    ticker: payload.ticker, verdict: 'CLEAR', confidence: 50,
    upgrade_signals: [], red_flags: ['claude_unavailable'],
    reason: 'Claude API key not configured', force_skip: false,
    size_view: 'full', _model: 'claude'
  };
  const text = await (async () => {
    const res = await http({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: { model: MODEL, max_tokens: 500, temperature: 0, system: (payload.systemPrompt + '\n\n' + PERSONA), messages: [{ role: 'user', content: payload.userPrompt }] },
      json: true, timeout: 45000
    });
    return (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
  })();
  return { ...parse(text, payload.ticker), raw_response: text, _model: "claude" };
}
const results = [];
for (const payload of data.councilPayloads || []) results.push(await callOne(payload));
return [{ json: { ["claudeResults"]: results, ...data } }];

const data = $input.first().json;
const apiKey = $vars.OPENAI_API_KEY || $env.OPENAI_API_KEY;
const MODEL = $vars.OPENAI_MODEL || 'gpt-4o';
const PERSONA = "You are the MOMENTUM CHASER. Focus on whether trend, volume, and catalyst are strong enough to sustain a 2-10 day move. What would stop this momentum?";
const http = this.helpers.httpRequest.bind(this);
function fallback(ticker, reason='Model returned unparseable response') {
  return { ticker, verdict: 'CLEAR', confidence: 50, upgrade_signals: [], red_flags: ['parse_error'], reason, force_skip: false, size_view: 'full' };
}
function sanitize(p, ticker) {
  const verdicts = ['STRONG','CLEAR','WEAK','SKIP','FORCE_SKIP'];
  const sizes = ['increase','full','reduce','half','zero'];
  p.ticker = ticker;
  p.verdict = verdicts.includes(String(p.verdict).toUpperCase()) ? String(p.verdict).toUpperCase() : 'CLEAR';
  p.confidence = Math.max(0, Math.min(100, Math.round(Number(p.confidence ?? 50))));
  p.upgrade_signals = Array.isArray(p.upgrade_signals) ? p.upgrade_signals : [];
  p.red_flags = Array.isArray(p.red_flags) ? p.red_flags : [];
  p.reason = String(p.reason || '').split(/\s+/).slice(0,25).join(' ') || 'No specific concern found';
  p.force_skip = p.force_skip === true || p.verdict === 'FORCE_SKIP';
  p.size_view = sizes.includes(p.size_view) ? p.size_view : (p.verdict === 'SKIP' || p.force_skip ? 'zero' : 'full');
  return p;
}
function parse(text, ticker) {
